-- Идемпотентно: можно запускать повторно.
--
-- Что делает:
--   1. Добавляет 36 мероприятий по 9 тематическим кластерам.
--   2. Назначает теги всем новым событиям.
--   3. Задаёт «вкус» тестового пользователя egor@demo.ru:
--      интересы (Робототехника/Электроника/Программирование),
--      регистрации ×5, избранное ×3, просмотры ×1 (+немного шума).
--
-- Ожидаемый результат в ленте Егора:
--   Вверху  — робототехника/электроника/программирование,
--   внизу   — дизайн/биология/космос (шумовые кластеры).
--
-- Пароль демо-аккаунтов: demo1234
-- ============================================================

-- ---------- 36 новых мероприятий ----------
insert into public.events (id, author_id, title, description, format, place, starts_at, registration_deadline, status, capacity) values
  -- Кластер A: Робототехника + Электроника (должны подняться наверх)
  ('aaaaaaaa-0000-4000-8000-00000000b001', '11111111-1111-4111-8111-111111111111', 'Соревнование «Битва роботов»', 'Турнир роботов-сумоистов: соберите робота на Arduino или ESP32, который вытолнет соперника за границы ринга. Вес до 1 кг, автономное питание. Призы от технопарка.', 'case', 'ЦДТ «Ритм», спортзал', now() + interval '5 days', now() + interval '3 days', 'published', 16),
  ('aaaaaaaa-0000-4000-8000-00000000b002', '11111111-1111-4111-8111-111111111111', 'Мастерская «Пайка без страха»', 'Практикум по пайке для начинающих: научимся собирать простые схемы на макетной плате, паять провода и чипы. Каждый уйдёт со своим рабочим мигающим светофором.', 'lecture', 'Технопарк, лаборатория 305', now() + interval '4 days', now() - interval '1 day', 'published', 12),
  ('aaaaaaaa-0000-4000-8000-00000000b003', '11111111-1111-4111-8111-111111111111', 'Кейс-чемпионат «Умный дом»', 'Спроектируйте фрагмент умного дома: датчики температуры и движения, автоматическое освещение, управление через приложение. Прототип на ESP32 с Wi-Fi.', 'case', 'Школа № 9, каб. 12', now() + interval '18 days', now() + interval '15 days', 'published', 10),
  ('aaaaaaaa-0000-4000-8000-00000000b004', '11111111-1111-4111-8111-111111111111', 'Лекция «Дроны: как они летают»', 'Инженер-конструктор объясняет устройство квадрокоптера: полётные контроллеры, моторы, PID-регулирование. Живая сборка дрона прямо на сцене.', 'lecture', 'Онлайн (ссылка придёт на почту)', now() + interval '21 days', now() + interval '19 days', 'published', null),
  ('aaaaaaaa-0000-4000-8000-00000000b005', '11111111-1111-4111-8111-111111111111', 'Хакатон «Робо-футбол»', '48 часов на команду роботов, играющих в футбол: компьютерное зрение для поиска мяча, стратегия, механика удара. Финальный матч — перед жюри и зрителями.', 'case', 'Технопарк, ул. Ленина 50', now() + interval '30 days', now() + interval '27 days', 'published', 12),
  ('aaaaaaaa-0000-4000-8000-00000000b006', '11111111-1111-4111-8111-111111111111', 'Воркшоп «Arduino за один день»', 'С нуля до первого проекта за один день: светодиоды, кнопки, сервоприводы, датчики. Никакой теории без практики — каждый шаг сразу собираем руками.', 'lecture', 'ЦДТ «Ритм», каб. 204', now() + interval '9 days', now() + interval '7 days', 'published', 14),
  ('aaaaaaaa-0000-4000-8000-00000000b007', '11111111-1111-4111-8111-111111111111', 'Кейс «Робогонки по линии»', 'Гонки роботов, следующих по трассе с перекрёстками и развилками: датчики линии, ПИД-регулятор, оптимизация скорости. Побеждает стабильность, а не скорость.', 'case', 'Кванториум, трассовый зал', now() + interval '35 days', now() + interval '32 days', 'published', 20),
  ('aaaaaaaa-0000-4000-8000-00000000b008', '11111111-1111-4111-8111-111111111111', 'Лекция «Микроконтроллеры: ESP32 против Arduino»', 'Честное сравнение популярных платформ: производительность, Wi-Fi и Bluetooth, экосистема, цена. Разберём, что выбрать для школьного проекта и почему.', 'lecture', 'Онлайн (ссылка придёт на почту)', now() + interval '12 days', now() + interval '10 days', 'published', null),
  -- Кластер B: ИИ + Программирование
  ('aaaaaaaa-0000-4000-8000-00000000b009', '11111111-1111-4111-8111-111111111111', 'Хакатон «Нейросети для добра»', '24 часа на проект с ИИ для социальной проблемы: доступность среды, помощь пожилым, образование. API нейросетей предоставляем, менторы помогут с интеграцией.', 'case', 'Технопарк, ул. Ленина 50', now() + interval '25 days', now() + interval '22 days', 'published', 15),
  ('aaaaaaaa-0000-4000-8000-00000000b010', '11111111-1111-4111-8111-111111111111', 'Лекция «Python для анализа данных»', 'Первая лекция цикла о данных: pandas, графики, типичные ошибки новичков. Все примеры — на реальных городских датасетах.', 'lecture', 'Онлайн (ссылка придёт на почту)', now() - interval '12 days', now() - interval '14 days', 'published', null),
  ('aaaaaaaa-0000-4000-8000-00000000b011', '11111111-1111-4111-8111-111111111111', 'Кейс-чемпионат «Чат-бот для школы»', 'Разработайте бота-помощника школы: расписание, замены, вопросы про столовую. Оценивается полезность, качество диалога и аккуратность кода.', 'case', 'Школа № 9, актовый зал', now() + interval '16 days', now() + interval '13 days', 'published', 10),
  ('aaaaaaaa-0000-4000-8000-00000000b012', '11111111-1111-4111-8111-111111111111', 'Митап «Веб-разработка: React и Supabase»', 'Практикующие разработчики показывают, как собрать полноценное веб-приложение за вечер: фронтенд на React, база и авторизация на Supabase.', 'lecture', 'Коворкинг «Точка кипения»', now() + interval '11 days', now() + interval '9 days', 'published', 30),
  ('aaaaaaaa-0000-4000-8000-00000000b013', '11111111-1111-4111-8111-111111111111', 'Лекция «Как работает ChatGPT»', 'Нейросети простыми словами: токены, обучение, галлюцинации. После лекции вы будете понимать, почему бот иногда врёт и как спрашивать правильно.', 'lecture', 'Онлайн (ссылка придёт на почту)', now() + interval '8 days', now() + interval '6 days', 'published', null),
  ('aaaaaaaa-0000-4000-8000-00000000b014', '11111111-1111-4111-8111-111111111111', 'Кейс «Компьютерное зрение»', 'Обучите модель распознавать отсортированный мусор на фото: датасет соберём сами, разметим и натренируем классификатор. Нужен ноутбук с Python.', 'case', 'Технопарк, лаборатория 210', now() + interval '28 days', now() + interval '25 days', 'published', 8),
  -- Кластер C: Эко и устойчивость
  ('aaaaaaaa-0000-4000-8000-00000000b015', '11111111-1111-4111-8111-111111111111', 'Кейс-чемпионат «Вторая жизнь вещей»', 'Придумайте продукт из того, что обычно выбрасывают: апгрейд старой техники, мебель из поддонов, моды из ненужной одежды. Жюри — эко-активисты и дизайнеры.', 'case', 'Экоцентр', now() + interval '14 days', now() + interval '11 days', 'published', 12),
  ('aaaaaaaa-0000-4000-8000-00000000b016', '11111111-1111-4111-8111-111111111111', 'Эко-квест «Чистый парк»', 'Командный квест по городскому парку: сортируем находки, отвечаем на вопросы об экологии, ищем тайники. Перчатки и мешки выдадим, настроение приносите с собой.', 'lecture', 'Городской парк, главная арка', now() + interval '6 days', now() + interval '4 days', 'published', 50),
  ('aaaaaaaa-0000-4000-8000-00000000b017', '11111111-1111-4111-8111-111111111111', 'Лекция «Сортировка отходов: правда и мифы»', 'Что действительно перерабатывается, а что едет на полигон despite значок на упаковке. Представитель регионального оператора отвечает на неудобные вопросы.', 'lecture', 'Онлайн (ссылка придёт на почту)', now() - interval '8 days', now() - interval '10 days', 'published', null),
  ('aaaaaaaa-0000-4000-8000-00000000b018', '11111111-1111-4111-8111-111111111111', 'Кейс «Вертикальная ферма»', 'Спроектируйте грядку для школы: гидропоника, досветка LED, автоматический полив на Arduino. Урожай — к весеннему школьному салату.', 'case', 'Экоцентр, теплица', now() + interval '33 days', now() + interval '30 days', 'published', 8),
  -- Кластер D: Городская среда
  ('aaaaaaaa-0000-4000-8000-00000000b019', '11111111-1111-4111-8111-111111111111', 'Кейс «Доступный город»', 'Как сделать город удобным для маломобильных жителей: навигация, пандусы, транспорт. Решение может быть сервисом, картой или устройством.', 'case', 'Технопарк, ул. Ленина 50', now() + interval '20 days', now() + interval '17 days', 'published', 10),
  ('aaaaaaaa-0000-4000-8000-00000000b020', '11111111-1111-4111-8111-111111111111', 'Хакатон «Городские данные»', 'Работаем с открытыми данными города: транспорт, бюджет, экология. Соберите дашборд или сервис, который делает данные понятными жителям.', 'case', 'Городской хаб открытых данных', now() + interval '26 days', now() + interval '23 days', 'published', 12),
  ('aaaaaaaa-0000-4000-8000-00000000b021', '11111111-1111-4111-8111-111111111111', 'Лекция «Как устроены умные города»', 'Опыт Сингапура, Барселоны и Москвы: датчики трафика, умные остановки, цифровые двойники. Что из этого уже работает у нас?', 'lecture', 'Онлайн (ссылка придёт на почту)', now() + interval '13 days', now() + interval '11 days', 'published', null),
  -- Кластер E: 3D-печать
  ('aaaaaaaa-0000-4000-8000-00000000b022', '11111111-1111-4111-8111-111111111111', 'Воркшоп «Первая модель в 3D»', 'Освойте Tinkercad и подготовьте свою первую модель к печати: от идеи до слайсера. Готовые модели напечатаем при вас на принтерах кванториума.', 'lecture', 'Кванториум, лаборатория 3D', now() + interval '7 days', now() - interval '2 days', 'published', 10),
  ('aaaaaaaa-0000-4000-8000-00000000b023', '11111111-1111-4111-8111-111111111111', 'Кейс «Протез из принтера»', 'Разработайте недорогой кистевой протез, напечатанный на 3D-принтере: шарниры, тяги, примерка. Консультирует инженер-биомеханик.', 'case', 'Медтех-лаборатория', now() + interval '38 days', now() + interval '35 days', 'published', 8),
  ('aaaaaaaa-0000-4000-8000-00000000b024', '11111111-1111-4111-8111-111111111111', 'Лекция «Материалы для 3D-печати»', 'PLA, PETG, ABS, TPU: когда какой пластик выбрать, почему детали расслаиваются и как хранить филамент. Каталог образцов можно потрогать руками.', 'lecture', 'Онлайн (ссылка придёт на почту)', now() - interval '15 days', now() - interval '17 days', 'published', null),
  -- Кластер F: Дизайн (шумовой для теста)
  ('aaaaaaaa-0000-4000-8000-00000000b025', '11111111-1111-4111-8111-111111111111', 'Конкурс «Постер для хакатона»', 'Нарисуйте афишу ближайшего хакатона: формат А2, смелая типографика. Победитель получит мерч и увидит свой постер на всех площадках города.', 'case', 'Онлайн + Технопарк', now() + interval '10 days', now() + interval '8 days', 'published', 20),
  ('aaaaaaaa-0000-4000-8000-00000000b026', '11111111-1111-4111-8111-111111111111', 'Воркшоп «Figma с нуля»', 'Первый шаг в интерфейсы: фреймы, авто-лейаут, компоненты. За два часа соберём экран мобильного приложения и научимся работать в командах.', 'lecture', 'ЦДТ «Ритм», каб. 105', now() + interval '5 days', now() + interval '3 days', 'published', 15),
  ('aaaaaaaa-0000-4000-8000-00000000b027', '11111111-1111-4111-8111-111111111111', 'Кейс «Айдентика технопарка»', 'Разработайте фирменный стиль молодого технопарка: логотип, цвета, носители. Лучшие работы войдут в официальный брендбук.', 'case', 'Технопарк, коворкинг', now() + interval '24 days', now() + interval '21 days', 'published', 6),
  ('aaaaaaaa-0000-4000-8000-00000000b028', '11111111-1111-4111-8111-111111111111', 'Лекция «Типографика в интерфейсах»', 'Почему одни тексты читать легко, а другие — нет: шрифтовые пары, ритм, иерархия. Разбираем реальные сайты слушателей.', 'lecture', 'Онлайн (ссылка придёт на почту)', now() - interval '5 days', now() - interval '7 days', 'published', null),
  -- Кластер G: Космос (шумовой для теста)
  ('aaaaaaaa-0000-4000-8000-00000000b029', '11111111-1111-4111-8111-111111111111', 'Лекция «Как запустить спутник»', 'Инженер космической отрасли о том, как школьный кубсат становится реальным спутником: конструкторские стандарты, испытания, запуск.', 'lecture', 'Планетарий, большой зал', now() + interval '40 days', now() + interval '37 days', 'published', 60),
  ('aaaaaaaa-0000-4000-8000-00000000b030', '11111111-1111-4111-8111-111111111111', 'Кейс-чемпионат «Марсианская станция»', 'Спроектируйте жилой модуль марсианской базы: энергоснабжение, оранжерея, система жизнеобеспечения. Защита перед экспертами центра планетологии.', 'case', 'Технопарк, ул. Ленина 50', now() + interval '42 days', now() + interval '39 days', 'published', 12),
  ('aaaaaaaa-0000-4000-8000-00000000b031', '11111111-1111-4111-8111-111111111111', 'Ночь наблюдений «Звёзды над городом»', 'Выездная астрономическая ночь: телескопы, карта звёздного неба, термос с чаем. Запись закрыта — все места заняты, следите за следующим выездом.', 'lecture', 'Загородная площадка «Обсерватория»', now() + interval '9 days', now() - interval '3 days', 'published', 40),
  -- Кластер H: Биология (шумовой для теста)
  ('aaaaaaaa-0000-4000-8000-00000000b032', '11111111-1111-4111-8111-111111111111', 'Лекция «ДНК своими глазами»', 'Выделим ДНК клубники подручными средствами и разберёмся, как читают геномы. Настоящая молекулярная биология без сложных терминов.', 'lecture', 'Биолаб при университете', now() + interval '17 days', now() + interval '15 days', 'published', 25),
  ('aaaaaaaa-0000-4000-8000-00000000b033', '11111111-1111-4111-8111-111111111111', 'Практикум «Микромир под микроскопом»', 'Капля воды из лужи — это вселенная. Освоим световой микроскоп, найдём инфузорий и сделаем первые микрофотографии на смартфон.', 'lecture', 'Биолаб при университете', now() + interval '23 days', now() + interval '20 days', 'published', 12),
  ('aaaaaaaa-0000-4000-8000-00000000b034', '11111111-1111-4111-8111-111111111111', 'Экскурсия «Лаборатория биотеха»', 'Экскурсия на биотех-кампус: ферментёры, чистые зоны, как делают лекарства. Увидите производство глазами технолога.', 'lecture', 'Биотех-кампус', now() + interval '36 days', now() + interval '34 days', 'published', 20),
  -- Кластер I: общие митапы
  ('aaaaaaaa-0000-4000-8000-00000000b035', '11111111-1111-4111-8111-111111111111', 'Встреча выпускников «Карьера в IT»', 'Выпускники школьных кружков рассказывают, как пришли в профессию: стажировки, портфолио, собеседования. Вопросы можно задавать анонимно.', 'lecture', 'Онлайн (ссылка придёт на почту)', now() - interval '20 days', now() - interval '22 days', 'published', null),
  ('aaaaaaaa-0000-4000-8000-00000000b036', '11111111-1111-4111-8111-111111111111', 'Научный квиз «Технологии вокруг нас»', 'Командный квиз о технологиях в быту: от микроволновки до GPS. Шесть раундов, призы лучшей команде и утешительные грамоты всем.', 'lecture', 'Технопарк, кафе «Молекула»', now() + interval '15 days', now() + interval '13 days', 'published', 30)
